import { resolve } from 'node:path';
import { buildRegistry, serializeRegistry } from '@proto/registry';
import { defineConfig, type Plugin } from 'vite';

const repoRoot = resolve(import.meta.dirname, '../..');

/** Dev server: live /registry.json from prototypes/ (in the built site it is generated by site:build). */
const devRegistry = (): Plugin => ({
  name: 'proto:dev-registry',
  configureServer(server) {
    server.middlewares.use('/registry.json', (_req, res) => {
      res.setHeader('Content-Type', 'application/json');
      res.end(serializeRegistry(buildRegistry(repoRoot)));
    });
  },
});

export default defineConfig({
  base: '/',
  plugins: [devRegistry()],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    target: 'es2022',
    rolldownOptions: {
      input: { index: resolve(import.meta.dirname, 'index.html') },
    },
  },
  server: { host: '0.0.0.0' },
});
